import type { CSSProperties } from "react";
import { alongCurve } from "@/lib/leaf";

// The leaf artwork in public/leaves is 480 x 660 with the leaf base at (240, 628)
// and the tip 602 units above it. Replace those three files with cut-out photographs
// of the same proportions to change every leaf on the site. The current files are
// generated by scripts/render-leaves.mjs.
const ART = { width: 480, height: 660, baseX: 240, baseY: 628, length: 602 };
const artFile = (variant: number) => `/leaves/leaf-${(((variant - 1) % 3) + 3) % 3 + 1}.webp`;

/** A leaf image inside an SVG, base at the origin and tip `length` units straight up. */
export function LeafImage({ length, variant = 1 }: { length: number; variant?: number }) {
  const k = length / ART.length;
  return (
    <image
      href={artFile(variant)}
      x={-ART.baseX * k}
      y={-ART.baseY * k}
      width={ART.width * k}
      height={ART.height * k}
    />
  );
}

const STEM: Parameters<typeof alongCurve>[0] = [
  [200, 474],
  [168, 340],
  [236, 210],
  [200, 62],
];
const stemPath = `M${STEM[0]}C${STEM[1]} ${STEM[2]} ${STEM[3]}`;

// Mint grows its leaves in opposite pairs. Alternate pairs sit at right angles on a
// real stem, so every other pair is drawn shorter, as if turned toward the viewer.
const PAIRS = [
  { t: 0.2, length: 150, spread: 76 },
  { t: 0.4, length: 108, spread: 58 },
  { t: 0.58, length: 132, spread: 70 },
  { t: 0.74, length: 84, spread: 50 },
  { t: 0.87, length: 92, spread: 62 },
];

// Each fix to the practice is a leaf on the plant.
const TAGS = [
  "Phones answered",
  "Copays collected",
  "Visits prepared",
  "Charts finished",
  "Patients recalled",
  "Reviews earned",
];

const leaves = PAIRS.flatMap((pair, i) => {
  const { x, y, heading } = alongCurve(STEM, pair.t);
  return ([1, -1] as const).map((side) => {
    const rotation = heading + 90 + side * pair.spread;
    const rad = ((rotation - 90) * Math.PI) / 180;
    return {
      key: `${i}${side}`,
      x,
      y,
      rotation,
      side,
      length: pair.length,
      variant: i * 2 + (side === 1 ? 1 : 2),
      at: pair.t * 0.9 + (side === 1 ? 0 : 0.03),
      tipX: x + Math.cos(rad) * pair.length * 0.9,
      tipY: y + Math.sin(rad) * pair.length * 0.9,
      // Tags sit on the three long pairs, one on each side.
      tag: i % 2 === 0 ? TAGS[i + (side === 1 ? 0 : 1)] : null,
    };
  });
});
const tip = alongCurve(STEM, 1);

/**
 * A mint plant whose growth follows the `--grow` custom property (0 to 1).
 * Set it from a scroll handler, or add `grow-on-load` / `grow-on-reveal`.
 * Pass `relative` or `absolute` in className to place it.
 */
export function GrowingMint({
  tags = false,
  ground = false,
  className = "",
  style,
}: {
  tags?: boolean;
  /** Draw the shadow the plant casts on the ground. */
  ground?: boolean;
  className?: string;
  style?: CSSProperties;
}) {
  return (
    <div className={`aspect-[400/520] ${className}`} style={style} aria-hidden="true">
      <svg viewBox="0 0 400 520" className="absolute inset-0 size-full overflow-visible">
        {ground && <ellipse cx="200" cy="478" rx="120" ry="13" className="ground" />}
        <path d={stemPath} pathLength="1" className="stem fill-none stroke-[#1d4a2a]" strokeWidth="8" strokeLinecap="round" />
        <path d={stemPath} pathLength="1" className="stem fill-none stroke-[#4f8f4a]" strokeWidth="4.5" strokeLinecap="round" />
        <path d={stemPath} pathLength="1" className="stem fill-none stroke-[#9cc98a]/70" strokeWidth="1.2" strokeLinecap="round" transform="translate(-1.2 0)" />
        {leaves.map((leaf, i) => (
          <g key={leaf.key} transform={`translate(${leaf.x.toFixed(1)} ${leaf.y.toFixed(1)}) rotate(${leaf.rotation.toFixed(1)})`}>
            <g className="leaf" style={{ "--at": leaf.at } as CSSProperties}>
              <g className="sway" style={{ animationDelay: `${-i * 0.7}s` }}>
                <LeafImage length={leaf.length} variant={leaf.variant} />
              </g>
            </g>
          </g>
        ))}
        {[-38, 0, 38].map((angle, i) => (
          <g key={angle} transform={`translate(${tip.x} ${tip.y}) rotate(${tip.heading + 90 + angle})`}>
            <g className="leaf" style={{ "--at": 0.84 } as CSSProperties}>
              <g className="sway" style={{ animationDelay: `${-i}s` }}>
                <LeafImage length={angle === 0 ? 62 : 50} variant={i + 1} />
              </g>
            </g>
          </g>
        ))}
      </svg>
      {tags &&
        leaves.map(
          (leaf) =>
            leaf.tag && (
              <span
                key={leaf.key}
                className={`plant-tag absolute hidden rounded-full bg-white/90 px-3 py-1.5 text-[13px] font-semibold whitespace-nowrap text-forest shadow-[0_8px_24px_-8px_rgba(11,34,25,0.45)] ring-1 ring-forest/10 backdrop-blur sm:block ${
                  leaf.side === 1 ? "translate-x-2" : "-translate-x-[calc(100%+0.5rem)]"
                } -translate-y-1/2`}
                style={
                  {
                    left: `${(leaf.tipX / 400) * 100}%`,
                    top: `${(leaf.tipY / 520) * 100}%`,
                    "--at": leaf.at + 0.08,
                  } as CSSProperties
                }
              >
                {leaf.tag}
              </span>
            ),
        )}
    </div>
  );
}

/** A single loose leaf, for accents. Size it with a width class. */
export function LooseLeaf({
  variant = 1,
  className = "",
  style,
}: {
  variant?: number;
  className?: string;
  style?: CSSProperties;
}) {
  return (
    <svg viewBox={`0 0 ${ART.width} ${ART.height}`} aria-hidden="true" className={className} style={style}>
      <image href={artFile(variant)} width={ART.width} height={ART.height} />
    </svg>
  );
}

// Deterministic scatter, so server and browser render the same leaves.
const FALLING = Array.from({ length: 14 }, (_, i) => ({
  left: (i * 37 + 11) % 100,
  size: 20 + ((i * 13) % 26),
  duration: 10 + ((i * 7) % 9),
  delay: -((i * 5) % 14),
  drift: (i % 2 ? 1 : -1) * (30 + ((i * 17) % 60)),
}));

/** Leaves drifting down through a dark band. */
export function FallingLeaves() {
  return (
    <div aria-hidden="true" className="pointer-events-none absolute inset-0 overflow-hidden">
      {FALLING.map((leaf, i) => (
        <span
          key={i}
          className="falling-leaf absolute -top-16"
          style={
            {
              left: `${leaf.left}%`,
              width: leaf.size,
              animationDuration: `${leaf.duration}s`,
              animationDelay: `${leaf.delay}s`,
              "--drift": `${leaf.drift}px`,
            } as CSSProperties
          }
        >
          <LooseLeaf variant={i + 1} className={`w-full ${i % 3 === 0 ? "opacity-50 blur-[1.5px]" : "opacity-90"}`} />
        </span>
      ))}
    </div>
  );
}

/** A band of words sliding sideways, separated by leaves. */
export function Marquee({ words }: { words: string[] }) {
  const row = (hidden: boolean) => (
    <ul aria-hidden={hidden} className="flex shrink-0 items-center">
      {words.map((word, i) => (
        <li key={word} className="flex items-center font-display text-3xl whitespace-nowrap sm:text-5xl">
          <span className="px-6 sm:px-10">{word}</span>
          <LooseLeaf variant={i + 1} className="w-5 rotate-[55deg] sm:w-7" />
        </li>
      ))}
    </ul>
  );
  return (
    <div className="overflow-hidden border-y border-line bg-white py-6 sm:py-8">
      <div className="marquee flex w-max">
        {row(false)}
        {row(true)}
      </div>
    </div>
  );
}

/** A leaf used as a list bullet. */
export function LeafBullet({ index = 0 }: { index?: number }) {
  return <LooseLeaf variant={index + 1} className="mt-0.5 w-4 shrink-0 rotate-[35deg]" />;
}
